        test("backupPasswordKeystoreProtectionAndSchedule",()->{Context c=getTargetContext();var settings=new BackupSettings(c);var originalPreferences=new java.util.HashMap<String,Object>(c.getSharedPreferences("backup-settings",Context.MODE_PRIVATE).getAll());char[] password="scheduled backup secure password".toCharArray();try{settings.savePassword(password);check(java.util.Arrays.equals(settings.password(),password));check(!c.getSharedPreferences("backup-settings",Context.MODE_PRIVATE).getAll().toString().contains(new String(password)));settings.schedule(true,24);BackupJob.schedule(c);var scheduler=c.getSystemService(android.app.job.JobScheduler.class);check(scheduler.getAllPendingJobs().stream().anyMatch(j->j.getService().getClassName().equals(BackupJob.class.getName())&&j.isPersisted()));settings.schedule(false,24);BackupJob.schedule(c);}finally{java.util.Arrays.fill(password,'\0');var editor=c.getSharedPreferences("backup-settings",Context.MODE_PRIVATE).edit().clear();for(var entry:originalPreferences.entrySet()){Object value=entry.getValue();if(value instanceof String text)editor.putString(entry.getKey(),text);else if(value instanceof Boolean flag)editor.putBoolean(entry.getKey(),flag);else if(value instanceof Integer number)editor.putInt(entry.getKey(),number);}editor.commit();BackupJob.schedule(c);}});
