        test("deletedHistoricalFlavourKeepsReportsAndLegacyBackupDoesNotUndelete",()->fresh((s,file)->{String id=Ledger.id();var c=new CatalogStore(s);c.save(new Catalog.Product(id,"Historic deleted flavour",1,2,2,600,""));c.transfer(new Catalog.Transfer(Ledger.id(),Catalog.LEGACY,id,2,System.currentTimeMillis(),"Counted"));var sold=sale();c.stage(sold,id,false);s.recoverPending();s.acknowledge(sold.id());var old=Backup.decode(Backup.encode(s.fullBackup()));var before=Finance.summarize(new FinanceStore(s).result(),Finance.period("all",java.time.LocalDate.now()));c.remove(id);var current=Backup.decode(Backup.encode(s.fullBackup()));eq(Finance.summarize(new FinanceStore(s).result(),Finance.period("all",java.time.LocalDate.now())).flavourProfit(),before.flavourProfit());check(c.view().products().stream().anyMatch(p->p.id().equals(id)&&p.name().equals("Historic deleted flavour")));s.importBackup(old);check(c.view().deleted().contains(id));String other="deleted-backup-"+UUID.randomUUID()+".db";try(Store replacement=new Store(getTargetContext(),other)){replacement.importBackup(current);replacement.importBackup(current);check(new CatalogStore(replacement).view().deleted().contains(id));eq(replacement.snapshot().events().size(),current.events().size());for(var event:current.events())check(replacement.snapshot().events().stream().anyMatch(restored->Ledger.same(restored,event)));eq(Finance.summarize(new FinanceStore(replacement).result(),Finance.period("all",java.time.LocalDate.now())).flavourProfit(),before.flavourProfit());}finally{getTargetContext().deleteDatabase(other);}}));
